raw_response:
- hosts: postgresql_servers
  become: true
  vars:
    postgresql_version: "15"
    db_name: "my_app_db"
    db_user: "my_app_user"
    db_password: "CHANGEME_IN_VAULT" # Use Ansible Vault for this in production
    pg_hba_allowed_cidrs:
      - "10.0.0.0/8"
      - "192.168.1.0/24"
    postgresql_conf_settings:
      - { option: "listen_addresses", value: "'*'" }
      - { option: "max_connections", value: "250" }
      - { option: "shared_buffers", value: "1GB" }
      - { option: "effective_cache_size", value: "3GB" }
      - { option: "maintenance_work_mem", value: "256MB" }
      - { option: "checkpoint_completion_target", value: "0.9" }
      - { option: "wal_buffers", value: "16MB" }
      - { option: "default_statistics_target", value: "100" }
      - { option: "random_page_cost", value: "1.1" }
      - { option: "effective_io_concurrency", value: "200" }
      - { option: "work_mem", value: "8MB" }
      - { option: "min_wal_size", value: "1GB" }
      - { option: "max_wal_size", value: "4GB" }
      - { option: "max_worker_processes", value: "4" }
      - { option: "max_parallel_workers_per_gather", value: "2" }
      - { option: "max_parallel_workers", value: "4" }
      - { option: "max_parallel_maintenance_workers", value: "2" }

  pre_tasks:
    - name: Ensure dependencies are installed
      ansible.builtin.apt:
        name:
          - apt-transport-https
          - ca-certificates
          - gnupg
          - python3-psycopg2
        state: present
        update_cache: true

  tasks:
    - name: Add

